CREATE TABLE IF NOT EXISTS payment_gateways(name VARCHAR(20) PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0,test_mode TINYINT NOT NULL DEFAULT 0,config TEXT NULL,config_hash CHAR(64) NULL,verified_at DATETIME NULL,verified_ref VARCHAR(100) NULL,verified_config_hash CHAR(64) NULL,last_error VARCHAR(255) NULL,sort_order INT NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS booking_fee_rules(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope VARCHAR(10) NOT NULL,target_id BIGINT UNSIGNED NOT NULL,fee_toman INT UNSIGNED NOT NULL,active TINYINT NOT NULL DEFAULT 1,note VARCHAR(255) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY fee_target(scope,target_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS refunds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tx_id BIGINT UNSIGNED NULL UNIQUE,legacy_intent_id BIGINT UNSIGNED NULL UNIQUE,purpose VARCHAR(20) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,amount_toman INT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'pending',method VARCHAR(30) NULL,bank_reference VARCHAR(100) NULL,note VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,handled_at DATETIME NULL,handled_by_admin BIGINT UNSIGNED NULL,INDEX refund_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
